546:type PlanFields = { amount: string; start: string; every?: string; day?: string; end: string; sheet?: string };
548:/** Add a plan on the person's row: the new plan row's id, or null when refused. */
549:export async function addPlan(page: Page, personId: string, f: PlanFields): Promise<string | null> {
551:  const plans = r.locator('[data-testid^="plan-row-"]');
552:  const before = await ids(plans, 'plan-row-');
553:  await r.getByTestId('plan-form-amount').fill(f.amount);
554:  await r.getByTestId('plan-form-start').fill(f.start);
555:  await setField(r, 'plan-form-every', f.every);
556:  await setField(r, 'plan-form-day', f.day);
557:  await setField(r, 'plan-form-sheet', f.sheet);
558:  await r.getByTestId('plan-form-end').fill(f.end);
559:  await r.getByTestId('plan-form-submit').click();
562:    const now = (await freshRows(plans, 'plan-row-', before, []))[0];
565:  }, r.getByTestId('plan-error'), 'add plan');
569:/** Pause (true) or resume (false) a plan: true once the plan shows it. */
570:export async function planPause(page: Page, planId: string, on: boolean): Promise<boolean> {
571:  const r = page.getByTestId(`plan-row-${planId}`);
572:  const done = async () => (await shown(r.getByTestId('plan-paused'))) === (on ? 'yes' : 'no');
574:  await r.getByTestId(on ? 'plan-pause' : 'plan-resume').click();
575:  return until(page, done, r.getByTestId('plan-error'), 'plan pause', already);
578:/** Change a plan's amount: true once the plan shows one more change line. */
579:export async function planAmount(page: Page, planId: string, amount: string): Promise<boolean> {
580:  const r = page.getByTestId(`plan-row-${planId}`);
581:  const lines = r.getByTestId('plan-change-line');
583:  await r.getByTestId('plan-amount').fill(amount);
584:  await r.getByTestId('plan-amount-save').click();
585:  return until(page, async () => (await lines.count()) > was, r.getByTestId('plan-error'), 'plan amount');
588:/** Generate the plans' claims: how many were made, or null when refused. */
589:export async function generatePlans(page: Page): Promise<number | null> {
590:  const cell = page.getByTestId('plan-generated-count');
592:  await page.getByTestId('plan-generate').click();
593:  const n = await countAfter(page, cell, page.getByTestId('plan-generate-error'), 'generate plans', was);

