# Check every pasted line by the claim form's rules first so a refusal writes nothing, then add a draft claim per
# line, in order. Responds with how many were added, and the claims.
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.paste.AddPastedClaims
  govern: [ transaction ]
# Validate before load so an invalid body is a 400, not masked by a 404. Responds with the sheet's claims.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.claim.BuildClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
