package net.officefloor.hq.app.patron;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/** Names someone else on the sheet as one of the person's patrons; refused for themselves or a patron already named. */
public class AddPatron {
    public void add(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @RequestBody PatronRequest request, People people, Patrons patrons, Audit audit)
            throws InvalidPatronException {
        Person patron = request == null || request.patron() == null ? null : people.find(sheet, request.patron());
        if (patron == null) {
            throw new InvalidPatronException("A patron must be someone on the sheet");
        }
        if (patron.id() == person.id()) {
            throw new InvalidPatronException("A person cannot be their own patron");
        }
        if (patrons.has(sheet, person.id(), patron.id())) {
            throw new InvalidPatronException(patron.name() + " is already a patron of " + person.name());
        }
        patrons.add(sheet, person.id(), patron.id());
        audit.record("PATRON_ADDED sheet=" + sheet + " by=" + user + " name=" + person.name() + " patron="
                + patron.name());
    }
}
package net.officefloor.hq.app.patron;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPatron {
    public void handle(@Parameter InvalidPatronException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.patron;

/** The patron is not someone else on the sheet, or is already one of the person's patrons. */
public class InvalidPatronException extends Exception {
    public InvalidPatronException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.patron;

/** That {@code patron} is one of {@code person}'s patrons: both are ids of people on the same sheet. {@code named}
 *  orders a person's patrons as they were named (lower first). */
public record Patron(long person, long patron, long named) {
}
package net.officefloor.hq.app.patron;

/** Body of POST /api/sheets/{sheet}/people/{person}/patrons: the id of the person named as patron. */
public record PatronRequest(Long patron) {
}
package net.officefloor.hq.app.patron;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The patrons each person on a sheet has named. */
@Repository
public class Patrons {

    private static final RowMapper<Patron> ROW = (rs, i) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id"),
            rs.getLong("named"));

    private final JdbcTemplate jdbc;

    public Patrons(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every patron named on the sheet, each person's in the order they were named. */
    public List<Patron> list(String sheet) {
        return jdbc.query("SELECT person_id, patron_id, named FROM patron WHERE sheet = ? ORDER BY person_id, named", ROW,
                sheet);
    }

    /** Whether the person has already named this patron. */
    public boolean has(String sheet, long person, long patron) {
        Integer found = jdbc.queryForObject(
                "SELECT COUNT(*) FROM patron WHERE sheet = ? AND person_id = ? AND patron_id = ?", Integer.class, sheet,
                person, patron);
        return found != null && found > 0;
    }

    public void add(String sheet, long person, long patron) {
        jdbc.update("INSERT INTO patron (sheet, person_id, patron_id) VALUES (?, ?, ?)", sheet, person, patron);
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with every patron named on the sheet. */
public class RespondWithPatrons {
    public void respond(@PathVariable("sheet") String sheet, Patrons patrons, ObjectResponse<List<Patron>> response) {
        response.send(patrons.list(sheet));
    }
}
-- The patrons a person has named on the sheet: other people on it, each at most once.
CREATE TABLE patron (
    sheet     VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    patron_id BIGINT       NOT NULL,
    PRIMARY KEY (sheet, person_id, patron_id)
);
-- The order a person named their patrons in: the first-named patron has the lowest. Shares follow this order.
ALTER TABLE patron ADD COLUMN named BIGINT GENERATED BY DEFAULT AS IDENTITY;
