import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** That `patron` is one of `person`'s patrons: both are ids of people on the sheet. `named` orders a person's patrons
 *  as they were named (lower first). */
export type Patron = { person: number; patron: number; named: number };

export const patronsKey = (sheet: string) => ['patrons', sheet] as const;

export const patronsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/patrons`;

/** Every patron named on the sheet. */
export function usePatrons(sheet: string) {
  return useQuery({
    queryKey: patronsKey(sheet),
    queryFn: () => getJson<Patron[]>(patronsPath(sheet)),
  });
}

/** Shares (in hundredths of a percent) for `count` patrons in the order they were named: 100.00 split equally, each
 *  rounded half to even to two decimals, with the remainder (100.00 minus the shares added up) on the first. */
export function shareCents(count: number): bigint[] {
  if (count === 0) return [];
  const n = BigInt(count);
  let each = 10000n / n;
  const twice = (10000n % n) * 2n;
  if (twice > n || (twice === n && each % 2n === 1n)) each += 1n;
  const shares = Array.from({ length: count }, () => each);
  shares[0] += 10000n - each * n;
  return shares;
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { peoplePath, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { recentSettledCents, useClaims } from '../claims/claims';
import { twoDecimals } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { patronsKey, shareCents, usePatrons } from './patrons';
import type { Patron } from './patrons';

/** A figure in ten-thousandths of a hundredth (hundredths times a share in hundredths of a percent) as hundredths,
 *  rounded half to even. */
function roundHundredths(product: bigint): bigint {
  const abs = product < 0n ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
  return product < 0n ? -quotient : quotient;
}

function PatronsHeader() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

// A person's patrons, each with their share (see shareCents; shown "<name> <share>", sorted by name, comma separated),
// and their backing: over the patrons, each patron's settled figures of their SETTLED claims dated within the 90 days up
// to and including the sheet's today, times their share divided by 100, added up and rounded half to even (0.00 with
// none). A patron is picked from the others on the sheet and named one at a time; the server refuses a patron already
// named.
function PersonPatrons({ sheet, user, person }: { sheet: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: everyone = [] } = usePeople(sheet);
  const { data: patrons = [] } = usePatrons(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const today = useSheetToday(sheet);
  const [picked, setPicked] = useState('');

  const mine = patrons
    .filter((p) => p.person === person.id)
    .sort((a, b) => a.named - b.named)
    .map((p) => everyone.find((e) => e.id === p.patron))
    .filter((p): p is Person => p !== undefined);
  const shares = shareCents(mine.length);
  const named = mine.map((p, i) => ({ patron: p, share: shares[i] }));
  const names = [...named]
    .sort((a, b) => a.patron.name.localeCompare(b.patron.name))
    .map((n) => `${n.patron.name} ${twoDecimals(n.share)}`);
  const backing = roundHundredths(
    named.reduce((sum, n) => sum + recentSettledCents(claims, n.patron, today) * n.share, 0n),
  );
  const others = everyone.filter((p) => p.id !== person.id);

  const add = useMutation({
    mutationFn: (patron: number) =>
      postJson<Patron[]>(byUser(`${peoplePath(sheet)}/${person.id}/patrons`, user), { patron }),
    onSuccess: (updated) => {
      queryClient.setQueryData(patronsKey(sheet), updated);
      setPicked('');
    },
  });
  const send = useSubmitOnce(add);

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{twoDecimals(backing)}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={picked}
          onChange={(e) => {
            setPicked(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {others.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => send(picked === '' ? -1 : Number(picked))}
        >
          Add patron
        </button>
        {add.isError && (
          <span data-testid="person-patron-error" role="alert">
            {' '}A patron must be someone else on the sheet, not already named.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 50, Component: PatronsHeader }),
  PersonColumns.fill({ order: 50, Component: PersonPatrons }),
];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

