import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/**
 * Extra columns of the people table. A column fills both regions: its header cell in
 * PersonColumnHeaders and, per person, its <td> in PersonColumns (inside `person-row-<id>`).
 */
export const PersonColumnHeaders = defineSlot<{ sheet: string; user: string }>('person.column-headers');
export const PersonColumns = defineSlot<{ sheet: string; user: string; person: Person }>('person.columns');
import { defineSlot } from '../Slot';

/**
 * The home screen's body once a user is signed in and a sheet is loaded. Everything in the app is
 * kept per sheet, so each panel receives the active sheet id and the signed-in user.
 */
export const SheetPanels = defineSlot<{ sheet: string; user: string }>('sheet.panels');
import { useState, type FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey, claimsPath } from './claims';
import type { Claim } from './claims';

type Pasted = { added: number; claims: Claim[] };

// The paste box: lines of name,amount,date,note (the note may hold commas; a blank date is the sheet's today; the
// note may be absent; a note ending in " #<reference>" gives the claim's reference) each add a DRAFT claim, in order, for the person of that name on the sheet (ignoring case).
// The server checks every line by the claim form's rules first, so a refusal adds nothing. Shows how many were added.
function PasteClaims({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const paste = useMutation({
    mutationFn: (body: string) => postJson<Pasted>(byUser(`${claimsPath(sheet)}/paste`, user), { text: body }),
    onSuccess: (result) => {
      queryClient.setQueryData(claimsKey(sheet), result.claims);
      setText('');
    },
  });
  const send = useSubmitOnce(paste);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(text);
  };

  return (
    <form onSubmit={submit}>
      <label>
        Paste claims (name,amount,date,note per line)
        <br />
        <textarea
          data-testid="paste-claims"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            paste.reset();
          }}
        />
      </label>
      <br />
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add pasted claims
      </button>
      {paste.isSuccess && (
        <>
          {' '}Added <strong data-testid="paste-added">{paste.data.added}</strong>
        </>
      )}
      {paste.isError && (
        <span data-testid="paste-error" role="alert">
          {' '}Nothing was added: every line needs a name on the sheet and an amount of 0.00 or more with up to two
          decimals, dated outside any closed period and not after the person's retirement.
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 23, Component: PasteClaims });
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

// Sends a mutation unless one sent this way has not answered yet, so a form submitted twice in quick
// succession (a double click) stores one record. `isPending` only shows on the next render, too late
// for the second click; this guard is a ref, set before the first send returns.
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, unknown, V, unknown>) {
  const busy = useRef(false);
  return (vars: V) => {
    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation
      .mutateAsync(vars)
      .catch(() => {
        /* a refusal shows through the mutation's own error state */
      })
      .finally(() => {
        busy.current = false;
      });
  };
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell one refusal from another. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date the screen shows the sheet as of (search param `asof`), or '' when it shows it as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"|"$/g, '');
}

/** Every request carries the screen's as-of date: the server answers each read as the sheet stood then, and
 *  refuses every write while it is set. */
function withAsOf(path: string): string {
  const asOf = currentAsOf();
  return asOf ? `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}` : path;
}

async function send<T>(path: string, init?: RequestInit, now = false): Promise<T> {
  const res = await fetch(now ? path : withAsOf(path), init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

/** A read answered as the sheet is now, whatever the screen's as-of date. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path, undefined, true);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

